SELECT asset.id_tournament,asset.workshop_id,asset.file_uid,asset.level_name, asset.author,asset.collaborators,asset.override_author_name,asset.object_key, asset.content_sha256,asset.byte_size,tournament.slug AS tournament_slug, to_char(tournament.end_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS tournament_end_at FROM zc_private.track_tournament_lobby_asset asset JOIN public.track_tournament tournament ON tournament.id=asset.id_tournament WHERE tournament.type=$1 AND tournament.start_at<=clock_timestamp() ORDER BY (tournament.end_at>clock_timestamp()) DESC,tournament.start_at DESC LIMIT 1
